size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image, QuantumType quantum_type,
                           unsigned char *compact_pixels, MagickOffsetType size_offset,
                           MagickBooleanType separate, ExceptionInfo *exception) {
  size_t count = 0;
  MagickBooleanType status = MagickTrue;
  unsigned char *blob = NULL;
  size_t row = 0;

  if ((psd_info->compression == 1) || (psd_info->compression == 2)) {
    /* Handle RLE or ZIP compression */
    for (row = 0; row < image->rows; row++) {
      register Quantum
        *p;

      register ssize_t
        x;

      unsigned char
        *pixels;

      p = SetImagePixels(next_image, 0, row, image->columns, 1);
      if (p == (Quantum *) NULL)
        break;
      if (!GetPixelInfo(image, quantum_type, next_image))
        break;
      pixels = (unsigned char *) AcquireQuantumMemory(image->columns, sizeof(*pixels));
      if (pixels == (unsigned char *) NULL) {
        IncompletePSDExportBlob(psd_info, size_offset, 0);
        break;
      }
      for (x = 0; x < (ssize_t) image->columns; x++) {
        pixels[x] = (unsigned char) GetPixelRed(next_image, p);
        p += GetPixelChannels(next_image);
      }
      if (psd_info->compression == 1)
        status = RLECompress(pixels, image->columns, &blob, &count, exception);
      else if (psd_info->compression == 2) {
        /* Handle ZIP compression */
        status = ZIPCompress(pixels, image->columns, &blob, &count, exception);
      }
      if (!status)
        break;
      RelinquishMagickMemory(pixels);
    }
  }

  IncompletePSDExportBlob(psd_info, size_offset, count);
  RelinquishMagickMemory(blob);
  return count;
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
  size_t total_bytes = 0;
  MagickBooleanType is_monochrome = MagickFalse;
  MagickOffsetType offset = 0;
  ssize_t y;
  unsigned char *pixels = NULL;
  size_t rows_per_strip = 1;
  size_t strip_size = 0;
  unsigned char *compressed_data = NULL;

  if (psd_info->number_channels == 1)
    is_monochrome = MagickTrue;

  if (psd_info->compression == ZIP)
  {
    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      pixels = (unsigned char *) AcquireQuantumInfoImage(image_info, image, quantum_type, exception);
      ExportQuantumPixels(image, (CacheView *) NULL, quantum_type, 1, (ssize_t) y, pixels, exception);

      strip_size = (size_t) (image->columns * 4);
      compressed_data = (unsigned char *) AcquireMemory(strip_size);
      CompressZip((const unsigned char *) pixels, image->columns, 1, compressed_data, &strip_size);

      (void) memcpy(compact_pixels + offset, compressed_data, strip_size);
      offset += strip_size;
      total_bytes += strip_size;

      compressed_data = RelinquishMagickMemory(compressed_data);
      pixels = (unsigned char *) RelinquishQuantumMemory(pixels);
    }
  }
  else if (psd_info->compression == RLE)
  {
    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      pixels = (unsigned char *) AcquireQuantumInfoImage(image_info, image, quantum_type, exception);
      ExportQuantumPixels(image, (CacheView *) NULL, quantum_type, 1, (ssize_t) y, pixels, exception);

      strip_size = (size_t) (image->columns * 4);
      compressed_data = (unsigned char *) AcquireMemory(strip_size);
      CompressRLE((const unsigned char *) pixels, image->columns, 1, compressed_data, &strip_size);

      (void) memcpy(compact_pixels + offset, compressed_data, strip_size);
      offset += strip_size;
      total_bytes += strip_size;

      compressed_data = RelinquishMagickMemory(compressed_data);
      pixels = (unsigned char *) RelinquishQuantumMemory(pixels);
    }
  }
  else
  {
    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      pixels = (unsigned char *) AcquireQuantumInfoImage(image_info, image, quantum_type, exception);
      ExportQuantumPixels(image, (CacheView *) NULL, quantum_type, 1, (ssize_t) y, pixels, exception);

      (void) memcpy(compact_pixels + offset, pixels, image->columns * 4);
      offset += image->columns * 4;
      total_bytes += image->columns * 4;

      pixels = (unsigned char *) RelinquishQuantumMemory(pixels);
    }
  }

  return total_bytes;
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset,
                           MagickBooleanType separate, ExceptionInfo *exception) {
  size_t count = 0;
  MagickBooleanType status = MagickFalse;
  size_t length = 0;
  ssize_t y;
  unsigned char *pixels = (unsigned char *) NULL;
  size_t scanline_size = (size_t) (image->columns * sizeof(Quantum));

  if (image->depth == 1)
    scanline_size = (image->columns + 7) / 8;

  if (psd_info->compression == 1)
  {
    scanline_size = RLECompress((const unsigned char *) compact_pixels,
                                compact_pixels, (size_t) image->columns, 1,
                                (ssize_t) image->rows);
    count = scanline_size;
  }
  else
  {
    for (y = 0; y < (ssize_t) image->rows; y++)
    {
      length = ExportImagePixelData(next_image, quantum_type, 1, (size_t) y, 0,
                                    (ssize_t) image->columns, 1, &pixels,
                                    exception);
      if (length == 0)
        break;
      count += length;
    }
    if (y < (ssize_t) image->rows)
      return(count);
    if (psd_info->compression == 2)
    {
      size_t compressed_size = 0;
      unsigned char *compressed_pixels = (unsigned char *) NULL;

      if ((compressed_pixels = (unsigned char *) AcquireQuantumMemory(1,
         sizeof(*compressed_pixels) * (image->rows * scanline_size + 12))) != NULL)
      {
        compressed_size = image->rows * scanline_size + 12;
        status = ZipCompress(pixels, (size_t) image->rows * scanline_size,
                             compressed_pixels, &compressed_size,
                             MagickTrue, exception);
        if (status != MagickTrue)
        {
          compressed_size = 0;
          (void) ThrowMagickException(exception, GetMagickModule(),
                                     CoderError,"PSDCompressionFailed","`%s'",
                                      image_info->filename);
        }
        count = compressed_size;
        pixels = compressed_pixels;
      }
    }
    else if (psd_info->compression == 3)
    {
      size_t compressed_size = 0;
      unsigned char *compressed_pixels = (unsigned char *) NULL;

      if ((compressed_pixels = (unsigned char *) AcquireQuantumMemory(1,
         sizeof(*compressed_pixels) * (image->rows * scanline_size + 12))) != NULL)
      {
        compressed_size = image->rows * scanline_size + 12;
        status = ZipCompress(pixels, (size_t) image->rows * scanline_size,
                             compressed_pixels, &compressed_size, MagickFalse,
                             exception);
        if (status != MagickTrue)
        {
          compressed_size = 0;
          (void) ThrowMagickException(exception, GetMagickModule(),
                                      CoderError,"PSDCompressionFailed","`%s'",
                                      image_info->filename);
        }
        count = compressed_size;
        pixels = compressed_pixels;
      }
    }
  }
  if (pixels != compact_pixels)
    (void) WriteBlobMemory(image, size_offset, count, pixels);
  if (pixels != compact_pixels)
    pixels = (unsigned char *) RelinquishMagickMemory(pixels);
  return(count);
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
    size_t length = 0;
    MagickBooleanType status = MagickTrue;
    size_t number_pixels = 0;
    ssize_t y;
    unsigned char *pixels = NULL;
    size_t row_size = 0;
    size_t compressed_row_size = 0;
    unsigned char *compressed_pixels = NULL;

    if (image->monochrome)
        (void) SetImageProgress(image, SaveImageTag, 0, 100);

    if (psd_info->compression == PSDNoCompression) {
        for (y = 0; y < (ssize_t) image->rows; y++) {
            length += WriteBlobMemory(image, size_offset + length, compact_pixels + y * row_size, row_size);
        }
    }
    else if (psd_info->compression == PSDRLECompression) {
        for (y = 0; y < (ssize_t) image->rows; y++) {
            pixels = ExportImagePixels(image, 0, y, image->columns, 1,
                                       quantum_type, pixels, exception);
            if (pixels == (unsigned char *) NULL) {
                status = MagickFalse;
                break;
            }
            compressed_pixels = CompressRLE(pixels, image->columns, &compressed_row_size, exception);
            if (compressed_pixels == (unsigned char *) NULL) {
                status = MagickFalse;
                break;
            }
            length += WriteBlobMemory(image, size_offset + length, compressed_pixels, compressed_row_size);
            compressed_pixels = (unsigned char *) RelinquishMagickMemory(compressed_pixels);
        }
    }
    else if (psd_info->compression == PSDZipCompression) {
        pixels = (unsigned char *) AcquireQuantumMemory(image->columns * image->rows, sizeof(*pixels));
        if (pixels == (unsigned char *) NULL) {
            status = MagickFalse;
        }
        else {
            for (y = 0; y < (ssize_t) image->rows; y++) {
                pixels = ExportImagePixels(image, 0, y, image->columns, 1,
                                           quantum_type, pixels, exception);
                if (pixels == (unsigned char *) NULL) {
                    status = MagickFalse;
                    break;
                }
            }

            if (status != MagickFalse) {
                compressed_pixels = CompressZIP(pixels, image->columns * image->rows,
                                                &compressed_row_size, exception);
                if (compressed_pixels == (unsigned char *) NULL)
                    status = MagickFalse;
                else
                    length += WriteBlobMemory(image, size_offset + length, compressed_pixels, compressed_row_size);
            }
            pixels = (unsigned char *) RelinquishMagickMemory(pixels);
        }
    }

    if (status == MagickFalse)
        (void) ThrowMagickException(exception, GetMagickModule(), ImageError,
                                    "UnableToWritePSDChannelBlob", "\n");

    return length;
}

size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
    size_t bytes_written = 0;
    MagickBooleanType is_monochrome = MagickFalse;

    if (image->depth == 1)
        is_monochrome = MagickTrue;

    if (psd_info->compression == ZIPCompression || psd_info->compression == ZIPWithPredictorCompression) {
        /* Handle ZIP compression logic here */
        for (size_t y = 0; y < image->rows; y++) {
            Quantum *pixels = (Quantum *) AcquireQuantumMemory(image->columns, sizeof(Quantum));
            ExportPixels(image, 0, y, image->columns, 1, quantum_type, pixels, exception);
            /* Apply ZIP compression on the pixels and write to blob */
            bytes_written += WriteBlob(next_image->blob, image->columns * sizeof(Quantum), pixels);
            pixels = (Quantum *) RelinquishMagickMemory(pixels);
        }
    } else if (psd_info->compression == RLECompression) {
        /* Handle RLE compression logic here */
        for (size_t y = 0; y < image->rows; y++) {
            Quantum *pixels = (Quantum *) AcquireQuantumMemory(image->columns, sizeof(Quantum));
            ExportPixels(image, 0, y, image->columns, 1, quantum_type, pixels, exception);
            /* Apply RLE compression on the pixels and write to blob */
            bytes_written += WriteBlob(next_image->blob, image->columns * sizeof(Quantum), pixels);
            pixels = (Quantum *) RelinquishMagickMemory(pixels);
        }
    } else {
        for (size_t y = 0; y < image->rows; y++) {
            Quantum *pixels = (Quantum *) AcquireQuantumMemory(image->columns, sizeof(Quantum));
            ExportPixels(image, 0, y, image->columns, 1, quantum_type, pixels, exception);
            /* Write raw pixel data to blob */
            bytes_written += WriteBlob(next_image->blob, image->columns * sizeof(Quantum), pixels);
            pixels = (Quantum *) RelinquishMagickMemory(pixels);
        }
    }

    return bytes_written;
}
